css:
.uic-pin-validator {
  --pv-bg: #f4eeda;
  --pv-ink: #000000;
  --pv-paper: #f8f8f6;
  --pv-lime: #d8f21a;
  --pv-magenta: #f1189f;
  --pv-blue: #1a5ce8;
  --pv-green: #92dc62;
  --pv-success-border: #5cb838;
  --pv-bw: 0.25em;

  width: 17.5em;
  display: flex;
  flex-direction: column;
  gap: 1.75em;
  font-family:
    system-ui,
    -apple-system,
    sans-serif;
  font-size: 1rem;
}

/* ─── Progress Bar ─── */
.uic-pin-validator__progress-track {
  width: 100%;
  height: 2.125em;
  box-sizing: border-box;
  background: var(--pv-paper);
  border: var(--pv-bw) solid var(--pv-ink);
  border-radius: 62.5em;
  box-shadow: 0.375em 0.375em 0 var(--pv-ink);
  padding: 0.25em;
  overflow: hidden;
}

.uic-pin-validator__progress-fill {
  height: 100%;
  background: var(--pv-lime);
  border-radius: 62.5em;
  animation: pv-progressFill 4s infinite ease-in-out;
}

/* ─── Fieldset ─── */
.uic-pin-validator__fieldset {
  background: var(--pv-bg);
  border: var(--pv-bw) solid var(--pv-ink);
  border-radius: 1.125em;
  padding: 1.625em 1.125em 1.375em;
  margin: 0;
  position: relative;
  box-shadow: 0.5em 0.5em 0 var(--pv-ink);
  transform: translateY(0) scale(1);
  animation: pv-fieldsetSuccess 4s infinite;
}

/* Hover / Focus / Active (guideline requirement) */
.uic-pin-validator__fieldset:hover {
  box-shadow: 0.625em 0.625em 0 var(--pv-ink);
  transform: translateY(-0.125em);
}

.uic-pin-validator__fieldset:focus-within {
  outline: 0.125em solid var(--pv-blue);
  outline-offset: 0.25em;
}

.uic-pin-validator__fieldset:active {
  transform: translateY(0.0625em);
  box-shadow: 0.25em 0.25em 0 var(--pv-ink);
}

/* ─── Legend ─── */
.uic-pin-validator__legend {
  font-weight: 900;
  font-size: 1em;
  letter-spacing: 0.0625em;
  color: var(--pv-ink);
  background: var(--pv-bg);
  border: var(--pv-bw) solid var(--pv-ink);
  border-radius: 0.75em;
  padding: 0.25em 1em;
  width: fit-content;
  min-width: 3.375em;
  margin-inline: auto;
  box-shadow: 0.25em 0.25em 0 var(--pv-ink);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  position: relative;
  animation: pv-legendFlash 4s infinite;
}

.uic-pin-validator__legend-text {
  white-space: nowrap;
  animation: pv-textFade 4s infinite;
}

.uic-pin-validator__legend::after {
  content: "✓";
  font-size: 1.75em;
  line-height: 1;
  position: absolute;
  opacity: 0;
  transform: scale(0.4);
  animation: pv-markFadeIn 4s infinite;
}

/* ─── Dots ─── */
.uic-pin-validator__dots {
  display: flex;
  justify-content: space-around;
  align-items: center;
  gap: 1em;
}

.uic-pin-validator__dot {
  width: 2.75em;
  height: 2.75em;
  border: var(--pv-bw) solid var(--pv-ink);
  border-radius: 50%;
  box-shadow: 0.3125em 0.3125em 0 var(--pv-ink);
  opacity: 0;
  transform: scale(1.7);
}

.uic-pin-validator__dot--1 {
  background: var(--pv-magenta);
  animation: pv-dotStamp1 4s infinite ease-out;
}
.uic-pin-validator__dot--2 {
  background: var(--pv-blue);
  animation: pv-dotStamp2 4s infinite ease-out;
}
.uic-pin-validator__dot--3 {
  background: var(--pv-lime);
  animation: pv-dotStamp3 4s infinite ease-out;
}
.uic-pin-validator__dot--4 {
  background: var(--pv-green);
  animation: pv-dotStamp4 4s infinite ease-out;
}

/* ═══════════════════════════════════════
   KEYFRAMES
   ═══════════════════════════════════════ */

@keyframes pv-progressFill {
  0%,
  5% {
    width: 0%;
  }
  60%,
  85% {
    width: 100%;
  }
  95%,
  100% {
    width: 0%;
  }
}

@keyframes pv-dotStamp1 {
  0%,
  5% {
    opacity: 0;
    transform: scale(1.7);
  }
  10%,
  85% {
    opacity: 1;
    transform: scale(1);
  }
  95%,
  100% {
    opacity: 0;
    transform: scale(1);
  }
}
@keyframes pv-dotStamp2 {
  0%,
  15% {
    opacity: 0;
    transform: scale(1.7);
  }
  20%,
  85% {
    opacity: 1;
    transform: scale(1);
  }
  95%,
  100% {
    opacity: 0;
    transform: scale(1);
  }
}
@keyframes pv-dotStamp3 {
  0%,
  25% {
    opacity: 0;
    transform: scale(1.7);
  }
  30%,
  85% {
    opacity: 1;
    transform: scale(1);
  }
  95%,
  100% {
    opacity: 0;
    transform: scale(1);
  }
}
@keyframes pv-dotStamp4 {
  0%,
  35% {
    opacity: 0;
    transform: scale(1.7);
  }
  40%,
  85% {
    opacity: 1;
    transform: scale(1);
  }
  95%,
  100% {
    opacity: 0;
    transform: scale(1);
  }
}

@keyframes pv-fieldsetSuccess {
  0%,
  60% {
    border-color: var(--pv-ink);
    box-shadow: 0.5em 0.5em 0 var(--pv-ink);
    transform: translateY(0) scale(1);
  }
  65%,
  85% {
    border-color: var(--pv-success-border);
    box-shadow:
      0.5em 0.5em 0 var(--pv-green),
      inset 0 0 0.75em rgba(146, 220, 98, 0.3);
    transform: translateY(-0.25em) scale(1.02);
  }
  95%,
  100% {
    border-color: var(--pv-ink);
    box-shadow: 0.5em 0.5em 0 var(--pv-ink);
    transform: translateY(0) scale(1);
  }
}

@keyframes pv-legendFlash {
  0%,
  60% {
    background: var(--pv-bg);
    border-color: var(--pv-ink);
    box-shadow: 0.25em 0.25em 0 var(--pv-ink);
  }
  65%,
  85% {
    background: var(--pv-green);
    border-color: var(--pv-success-border);
    box-shadow: 0.25em 0.25em 0 var(--pv-success-border);
  }
  95%,
  100% {
    background: var(--pv-bg);
    border-color: var(--pv-ink);
    box-shadow: 0.25em 0.25em 0 var(--pv-ink);
  }
}

@keyframes pv-textFade {
  0%,
  58% {
    opacity: 1;
    transform: scale(1);
  }
  65% {
    opacity: 0;
    transform: scale(0.8);
  }
  85% {
    opacity: 0;
    transform: scale(0.8);
  }
  92%,
  100% {
    opacity: 1;
    transform: scale(1);
  }
}

@keyframes pv-markFadeIn {
  0%,
  58% {
    opacity: 0;
    transform: scale(0.4);
  }
  65% {
    opacity: 1;
    transform: scale(1.1);
  }
  70%,
  85% {
    opacity: 1;
    transform: scale(1);
  }
  92%,
  100% {
    opacity: 0;
    transform: scale(0.4);
  }
}
